      "JavaScript simple solution [97%, 100%] i-love-typescript 1139 721 Apr 27, 2020 JavaScript Recursion Runtime: 84 ms, faster than 97.40% of JavaScript online submissions for Maximum Binary Tree. \nMemory Usage: 40.9 MB, less than 100.00% of JavaScript online submissions for Maximum Binary Tree. \n function constructMaximumBinaryTree ( nums )   { \n    return   next ( 0 ,  nums . length  -   1 ) ; \n   \n   function  next ( l ,  r )   { \n      if   ( l  >  r )   return  null ; \n     let maxIndex  =   - 1 ,   max   =   - Infinity ; \n      for   ( let i  =  l ;  i  <=  r ;  i + + )   { \n        if   ( nums [ i ]   >   max )   { \n         maxIndex  =  i ; \n          max   =  nums [ i ] ; \n        } \n      } \n      return   { \n       val :   max , \n       left :   next ( l ,  maxIndex  -   1 ) , \n       right :   next ( maxIndex  +   1 ,  r ) \n      } \n    } \n } Comments (1) mugaba Jul 25, 2020 can please explain the importance of l and r they are a bit confusing 0 Show 1 Replies Reply",
