      "Simple JS Solution w/ Comments - Two Pointers qkrrbtjd90 310 672 Aug 25, 2022 JavaScript Two Pointers /**\n  * *Time: O(N)\n  * *Space: O(N)\n  */ \n // Runtime: 434 ms, faster than 67.61% of JavaScript online submissions for Partition Array According to Given Pivot. \n // Memory Usage: 77.7 MB, less than 85.92% of JavaScript online submissions for Partition Array According to Given Pivot. \n const   pivotArray   =   ( nums ,  pivot )   =>   { \n \t let   N   =  nums . length ; \n \t let  output  =   [ ] ; \n \n    // pointers to iterate array from start/end \n \t let  i  =   0 ; \n \t let  j  =   N   -   1 ; \n \n    // pointers to save elements in correct spot \n \t let   L   =   0 ; \n \t let   R   =   N   -   1 ; \n \t\n \t // select elements starting from start and end of array \n \t // add elements to correct spot if conditions are met. \n \t while   ( i  <  nums . length )   { \n \t\t if   ( nums [ i ]   <  pivot )  output [ L ++ ]   =  nums [ i ] ; \n \t\t if   ( nums [ j ]   >  pivot )  output [ R -- ]   =  nums [ j ] ; \n \n \t\ti ++ ; \n \t\tj -- ; \n \t } \n \n \t // fill middle with pivot \n \t while   ( L   <=   R )   { \n \t\toutput [ L ++ ]   =  pivot ; \n \t } \n \n \t return  output ; \n } ; \n Comments (1) aaronsr Oct 28, 2022 Thanks. I was stuck on the logic of using the two-pointer system before I saw your post. 0 Reply",
      "All Solutions Simple JavaScript Solution(98%/95%) kubatabdrakhmanov 95 952 Oct 18, 2022 JavaScript  \n var   pivotArray   =   function ( nums ,  pivot )   { \n      let  smaller  =   [ ] ; \n      let  greater  =   [ ] ; \n      let  equal  =   [ ] ; \n      for ( let  i  =   0 ;  i  <  nums . length ;  i ++ ) { \n          if ( nums [ i ]   <  pivot )  smaller . push ( nums [ i ] ) \n          else   if ( nums [ i ]   >  pivot )  greater . push ( nums [ i ] ) \n          else  equal . push ( nums [ i ] ) \n      } \n      return  smaller . concat ( equal ,  greater ) \n } ; Comments (0) No comments yet. 1 2 3 4 5 6 class   Solution  { public:      vector < int >  pivotArray ( vector < int > &   nums ,  int   pivot ) {              } }; Saved Ln 1, Col 1 You need to  Login / Sign up  to run or submit nums = [9,12,5,10,14,3,10] pivot = 10 1 [9,12,5,10,14,3,10] Source word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word word mmMwWLliI0fiflO&1 mmMwWLliI0fiflO&1 mmMwWLliI0fiflO&1 mmMwWLliI0fiflO&1 mmMwWLliI0fiflO&1 mmMwWLliI0fiflO&1 mmMwWLliI0fiflO&1",
      "JavaScript 🔥⚡ very simple solution aswin_a_ 1 70 Apr 29, 2024 JavaScript Intuition \n\n Approach \n\n Complexity \n \n Time complexity: \n \n\n \n Space complexity: \n \n\n Code \n  \n var   pivotArray   =   function ( nums ,  pivot )   { \n      let  less  =   [ ] \n      let  greater  =   [ ] \n      let  same  =   [ ] \n      for ( let  num  of  nums )   { \n          if ( num  <  pivot )   { \n             less . push ( num ) \n          }   else   if   ( num  >  pivot )   { \n             greater . push ( num ) \n          }   else   { \n             same . push ( num ) \n          } \n      } \n      return   [ ... less ,   ... same ,   ... greater ] \n } ; Comments (1) nibiniz339 Apr 29, 2024 Very nice soln.......everyone pls follow 0 Reply",
