      "For Beginners like me(Runtime: 80 ms, faster than 83.90%,Memory Usage: 41 MB, less than 47.86% ) lssuseendharlal 196 1464 Feb 08, 2021 JavaScript Naive sol: \n var   sumOddLengthSubarrays   =   function ( arr )   { \n    let  count  =   0 ; \n    for   ( let  i  =   0 ;  i  <  arr . length ;  i ++ )   { \n        const  odd  =   [ ] ; \n      for   ( let  j  =  i ;  j  <  arr . length ;  j ++ )   { \n       odd . push ( arr [ j ] ) ; \n        if   ( odd . length   %   2   !==   0 )  count +=  odd . reduce ( ( acc , curr ) => acc + curr , 0 ) \n      } \n    } \n    return  count ; \n } ; \n Most Optimised sol: \nExplanation:  https://leetcode.com/problems/sum-of-all-odd-length-subarrays/discuss/867779/Java-O(n)-time-with-Video-explanation \n var   sumOddLengthSubarrays   =   function ( arr )   { \n      let  total = 0 \n     \n      for ( let  i = 0 ; i < arr . length ; i ++ ) { \n          const  endsWith = i + 1 \n          const  beginsWith = arr . length - i\n          const  totalOccurances = endsWith * beginsWith\n         total += ( totalOccurances - Math . floor ( totalOccurances / 2 ) ) * arr [ i ]    // totalOccurances-evenOccurances=oddOccurances \n      } \n      return  total\n } ; \n Runtime :   64  ms ,  faster than  95.91 %   of   JavaScript  online submissions  for   Sum   of   All   Odd   Length   Subarrays . \n Memory   Usage :   42.5   MB ,  less than  51.07 %   of   JavaScript  online submissions  for   Sum   of   All   Odd   Length   Subarrays Comments (2) AbdulKhader4123 Apr 17, 2021 Read more 4 Reply vishal238128 Jun 26, 2022 @lssuseendharlal  could you explain me your first answer (Naive sol:) 0 Show 1 Replies Reply",
      "O(N) time || O(1) Space || Heavily Commented || Ultra Simple Dawit-Melka 80 1322 Oct 14, 2022 JavaScript var   sumOddLengthSubarrays   =   function ( arr )   { \n      var  sum  =   0 ; \n      var  n  =  arr . length \n      for ( var  i = 0 ;  i  <  arr . length ;  i ++ ) { \n          var  s  =  n  -  i ;   // number of subarrays start with arr[i] \n          var  e  =  i  +   1 ;   // number of subarrays end with arr[i]; \n          // so the total subarray which include arr[i] is s*e \n          // so half of the sub arrays are odd so we devide it by two \n          // we multiply the number of occurence of the element in odd sub arrays with the element \n         sum  +=   ( ( Math . ceil ( ( s * e ) / 2 ) ) * arr [ i ] )  \n      } \n      return  sum ; \n } ; Comments (1) Phynnnix Oct 20, 2022 I needed a minute to see why  s*e  should equal the total of subarrays containing  arr[i] . That's an elegant way of calculating the number of subarrays. Mine was a bit more convoluted. 0 Reply",
      "🎅🎅BEATED 96% || JAVASCRIPT || AMAZINGLY EASY TO UNDERSTAND🎅🎅 sikkasakshi2 94 1738 Dec 22, 2022 JavaScript Code \n  \n var   sumOddLengthSubarrays   =   function   ( arr )   { \n      if   ( ! arr . length ) \n          return   0 \n      let  sum  =   0 \n      const   findSum   =   ( first ,  last )   =>   { \n          let  sum  =   0 \n          for   ( let  i  =  first ;  i  <=  last ;  i ++ ) \n             sum  +=  arr [ i ] \n          return  sum\n      } \n \n      for   ( let  i  =   0 ;  i  <  arr . length ;  i ++ )   { \n          for   ( let  j  =   0 ;   ( j  +  i )   <  arr . length ;  j  =  j  +   2 ) \n             sum  +=   findSum ( i ,  i  +  j ) \n      } \n      return  sum\n } ; Comments (3) rizviali983 Dec 22, 2022 a very new approach thank you 0 Reply Kanwalgulati Dec 22, 2022 nice Approach  ! Very easy to understand 🔥 🔥 0 Reply realnafees Dec 22, 2022 Came here for christmas gift ! 🎁🎁 🎅🎅 \nHAHAH 😛 😝 \nNice approach 🔥 🔥 0 Reply"
