      "Python/JS/Java/Go/C++ O(n) by iteration [w/ Comment] brianchiang_tw 6894 14637 Sep 09, 2020 C++ Java Python Python3 4+ O(n) by iteration \n 中文詳解 解題文章 \n Tutorial video in Chinese 中文解題影片 \n <img src=\"https://assets.leetcode.com/users/images/967ea20c-7acc-48ac-a4d5-60c8aa17316e_1615731413.5755115.png\" alt=\"image\"> \n \n Implementation : \n Python : \n class Solution:\n     def diagonalSum ( self ,  mat: List [ List [ int ] ] )   - >   int :\n         \n         n  =   len ( mat ) \n         \n         mid  =  n  // 2 \n         \n         summation  =   0 \n         \n          for  i  in  range ( n ) :\n             \n              # primary diagonal \n             summation  + =  mat [ i ] [ i ] \n             \n              # secondary diagonal \n             summation  + =  mat [ n - 1 - i ] [ i ] \n             \n             \n          if  n  %   2   = =   1 :\n              # remove center element (repeated) on odd side-length case \n             summation  - =  mat [ mid ] [ mid ] \n             \n             \n          return  summation \n \n Java : \n class   Solution   { \n      public   int   diagonalSum ( int [ ] [ ]  mat )   { \n         \n          // side length \n          int  n  =  mat . length ; \n         \n          // mid point index \n          int  mid  =  n  /   2 ; \n         \n          // summation of diagonal element \n          int  summation  =   0 ; \n         \n          for (   int  i  =   0   ;  i  <  n  ;  i ++   ) { \n             \n              // primary diagonal \n             summation  +=  mat [ i ] [ i ] ; \n             \n              // secondary diagonal \n             summation  +=  mat [ n - 1 - i ] [ i ] ; \n          } \n         \n         \n          if (  n  %   2   ==   1   ) { \n             \n              // remove center element (repeated) on odd side-length case \n             summation  -=  mat [ mid ] [ mid ] ; \n          } \n         \n          return  summation ; \n      } \n } \n \n Javascript : \n var   diagonalSum   =   function ( mat )   { \n     \n      // side length \n      let  n  =  mat . length ; \n     \n      // mid point index \n      let  mid  =   Math . floor (  n  /   2   ) ; \n     \n      // summation of diagonal element \n      let  summation  =   0 ; \n     \n      for (   let  i  =   0   ;  i  <  n  ;  i ++   ) { \n         \n          // primary diagonal \n         summation  +=  mat [ i ] [ i ] ; \n         \n          // secondary diagonal \n         summation  +=  mat [ n - 1 - i ] [ i ] ; \n      } \n     \n      if (  n  %   2   ==   1   ) { \n         \n          // remoive center element (repeated) on odd side-length case \n         summation  -=  mat [ mid ] [ mid ] ; \n      } \n     \n      return  summation ; \n } ; \n \n Golang : \n func   diagonalSum ( mat  [ ] [ ] int )   int   { \n     \n      // side-length \n     n  :=   len ( mat ) \n     \n      // mid point index \n     mid  :=  n  /   2 \n     \n      // summation of diagonal element \n     summation  :=   0 \n     \n      for  i  :=   0   ;  i  <  n  ;  i ++ { \n         \n          // primary diagonal \n         summation  +=  mat [ i ] [ i ] \n         \n          // secondary diagonal \n         summation  +=  mat [ n - 1 - i ] [ i ] \n         \n      } \n     \n      if  n  %   2   ==   1   { \n         \n          // remove center element (repeated) on odd side-length case \n         summation  -=  mat [ mid ] [ mid ] \n      } \n     \n     \n      return  summation\n } \n \n C++ : \n class   Solution   { \n public : \n      int   diagonalSum ( vector < vector < int >> &  mat )   { \n         \n          // side length \n          int  n  =  mat . size ( ) ; \n         \n          // mid point index \n          int  mid  =  n  /   2 ; \n         \n          // summation of diagonal element \n          int  summation  =   0 ; \n         \n          for (   int  i  =   0   ;  i  <  n  ;  i ++   ) { \n             \n              // primary diagonal \n             summation  +=  mat [ i ] [ i ] ; \n             \n              // secondary diagonal \n             summation  +=  mat [ n - 1 - i ] [ i ] ; \n          } \n         \n         \n          if (  n  %   2   ==   1   ) { \n             \n              // remove center element (repeated) on odd side-length case \n             summation  -=  mat [ mid ] [ mid ] ; \n          } \n         \n          return  summation ; \n      } \n } ; Comments (16) kaeid95 Sep 26, 2021 Read more 9 Show 2 Replies Reply liuvince Feb 16, 2021 Read more 6 Reply Vnode12 Jan 05, 2021 good solution. Easy to understand 4 Show 1 Replies Reply hritik5102 Jan 30, 2021 3 Reply rajanbhagat92 Oct 20, 2021 Read more 1 Reply pratik32 Jun 06, 2021 Read more 1 Reply leihao1313 Jan 05, 2021 1 Show 1 Replies Reply syed88 Sep 11, 2020 Read more 0 Reply alexandr-kazakov Jan 29, 2024 JavaScript solution Explanation in Russian [Video] \n Read more 0 Reply rohitramteke May 08, 2023 Read more 0 Show 2 Replies Reply",
      "[JavaScript] Simple solution using two pointers with explanation | O(n) mrhyde 224 1628 Nov 17, 2020 JavaScript Two Pointers I've seen many solutions using extra variables to keep track of rows and columns but since we are going in diagonal we can assume that coordinates for each cell in the matrix for our first diagonal line will be: \n x = i + 1\n y = i + 1 \n As for the other one, we will just go in the opposite direction and decrement by one starting from the last element in each row \nIf the indices collide we just skip the increment so we don't need to subtract later \n const   diagonalSum   =   ( mat )   =>   { \n    let  sum  =   0 \n    let  j  =  mat [ 0 ] . length   -   1 \n \n    for   ( let  i  =   0 ;  i  <  mat . length ;  i ++ ,  j -- )   { \n      if   ( i  !==  j ) \n       sum  +=  mat [ i ] [ j ] \n     sum  +=  mat [ i ] [ i ] \n    } \n \n    return  sum\n } \n Version with  forEach  (a bit easier to read): \n const   diagonalSum   =   ( mat )   =>   { \n    let  sum  =   0 \n    let  j  =  mat [ 0 ] . length   -   1 \n \n   mat . forEach ( ( row ,  i )   =>   { \n      if ( i  !==  j  -  i ) \n       sum  +=  row [ j  -  i ] \n     sum  +=  row [ i ] \n    } ) \n \n    return  sum\n } Comments (2) shamilrasheed131 Jan 26, 2023 Wow, this is a great and simple solution. 0 Reply alexandr-kazakov Jan 29, 2024 JavaScript solution Explanation in Russian [Video] \n Read more -1 Reply",
      "Simple Explanation! soluman_dawood 8 505 May 08, 2023 JavaScript Array Matrix There is an obvious pattern to follow and it's simple : \nLeft side : you will notice that we add to the sum by increasing the index by one each  loop => \n[ 6 , 3, 1, 10, 7, 4], \n[4,  10 , 1, 9, 5, 10], \n[5, 5,  7 , 3, 8, 5], \n[2, 7, 6,  4 , 7, 6], \n[7, 9, 6, 1,  8 , 5], \n[1, 7, 9, 5, 8,  4 ]] \n Also from the right : we decrease the index by one \n[6, 3, 1, 10, 7, 4 ], \n[4, 10, 1, 9,  5 , 10], \n[5, 5, 7,  3 , 8, 5], \n[2, 7,  6 , 4, 7, 6], \n[7,  9 , 6, 1, 8, 5], \n[ 1 , 7, 9, 5, 8, 4]] \n And as for this case : \n[1, 2, 3], \n[4, 5, 6], \n[7, 8, 9] \nwhere we shoud only add num 5 to the sum only once, So the condition is : \nif right == left we only take one of them (because they are equal and both of them returns the same number). \n the  final  solution \n var   diagonalSum   =   function ( mat )   { \n    let  left   =   0 ,  right  =  mat . length - 1 ,  sum  =   0 ; \n      for ( let   i =   0 ;  i  <  mat . length ;  i ++ )   { \n          if ( left  ==  right )  sum  +=  mat [ i ] [ left ] ; \n          else  sum  +=  mat [ i ] [ left ]   +  mat [ i ] [ right ] ; \n         left ++ ; \n         right -- ; \n      } \n      return  sum ; \n } ; \n Upvote if it was helpful Comments (3) freezingfire15 May 08, 2023 awesome solution!! 1 Show 1 Replies Reply myfootsasleep May 08, 2023 love the explanation and not just the solution 1 Show 1 Replies Reply alexandr-kazakov Jan 29, 2024 JavaScript solution Explanation in Russian [Video] \n Read more 0 Reply",
      "Very simple and easy JavaScript solution!!! Wow (0_o) AzamatAbduvohidov 166 1682 May 07, 2023 JavaScript Code \n  \n var   diagonalSum   =   function ( mat )   { \n      let  result  =   0 ; \n      let  left  =   0 ,  right  =  mat . length   -   1 ; \n      for ( let  i  =   0 ;  i  <  mat . length ;  i ++ )   { \n          if ( left  ==  right )   { \n             result  +=  mat [ i ] [ left ]   // or mat[i][right] \n          }   else   { \n             result  +=  mat [ i ] [ left ] \n             result  +=  mat [ i ] [ right ] \n          } \n         left ++ ; \n         right -- ; \n      } \n      return  result\n } ; Comments (6) AzamatAbduvohidov May 08, 2023 (☝️ ՞ਊ ՞)  - Please upvote 1 Reply NarutoUzumaki99 May 07, 2023 this answer easy to understand 1 Reply NarutoUzumaki99 May 07, 2023 Looks good 1 Reply 001SwetaSharma Aug 27, 2023 Good Solution!! \nCheck out this solution as well... tried to put a better approach ... :) \n https://leetcode.com/problems/matrix-diagonal-sum/solutions/3968510/faster-than-98-of-js-solutions-very-simple-straightforward-solution-o-n/ 0 Reply AzamatAbduvohidov May 07, 2023 and also press button favorite 0 Reply AzamatAbduvohidov May 07, 2023 If you liked please upvote 0 Reply",
      "Simple Javascript Solution NileshSaini_99 213 618 Sep 23, 2021 JavaScript var   diagonalSum   =   function ( mat )   { \n      let  primary  =   0 , \n         secondary  =   0 ; \n     \n \t // storing the sum of all vaues in both diagonals  \n      for ( let  i  =   0 ;  i  <  mat . length ;  i ++ )   { \n         primary  +=  mat [ i ] [ i ] ; \n         secondary  +=  mat [ i ] [ mat . length   -  i  -   1 ] ; \n         \n      } \n     \n \t // if its an odd matrix then we subtract the mid item form the total sum. Else we just return the primary and secondary sum; \n \t\n      if ( mat . length   ===  mat [ 0 ] . length   &&  mat [ 0 ] . length   %   2   !==   0 )   { \n          let  centerIdx  =   Math . floor ( mat . length / 2 ) ; \n          return  primary  +  secondary  -  mat [ centerIdx ] [ centerIdx ] ; \n      }   else   { \n          return  primary + secondary ; \n      } \n } ; Comments (1) Surya-teja Oct 01, 2021 the middle value is being added two time... 0 Show 1 Replies Reply"
