      "Typescript: easy solution with Set (Runtime beats 100%) alexgavrilov 125 178 Oct 28, 2023 JavaScript TypeScript Complexity \n \n \n Time complexity: \nO(n^2) \n \n \n Space complexity: \nO(n) \n \n \n Code \n function   sumCounts ( nums :   number [ ] ) :   number   { \n      const  counts :   number [ ]   =   [ ] ; \n      for   ( let  i  =   0 ;  i  <  nums . length ;  i ++ )   { \n          const  set  =   new   Set ( [ nums [ i ] ] ) ; \n          for   ( let  j  =  i ;  j  <  nums . length ;  j ++ )   { \n             set . add ( nums [ j ] ) ; \n             counts . push ( set . size   **   2 ) ; \n          } \n      } \n      let  sum :   number   =   0 ; \n     counts . forEach ( ( v )   =>  sum  +=  v ) ; \n \n      return  sum ; \n } ; \n \n Comments (1) narasimhakamath Feb 13, 2024 Why not just add it instead of pushing elements to an array and then looping through it to get the sum? This approach would take lesser memory, O(1). 0 Reply",
